  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  int i, k;

  /* Local non-aliasing pointers to help the compiler with vectorization
     and instruction scheduling.  PolyBench allocates r and y as distinct
     arrays, so adding 'restrict' here is safe. */
  const DATA_TYPE *restrict r_ = r;
  DATA_TYPE       *restrict y_ = y;

