  /* k = 0 initialization (same as original code). */
  y_[0] = -r_[0];
  beta  = SCALAR_VAL(1.0);
  alpha = -r_[0];

  /* Main Durbin recursion. This outer loop is inherently sequential due
     to dependences carried through alpha, beta and y[0..k]. */
