      int j = k - 1 - i;

      DATA_TYPE yi = y_[i]; /* old y[i] */
      DATA_TYPE yj = y_[j]; /* old y[j] */

      /* new y[i] = yi + alpha * yj */
      y_[i] = yi + alpha * yj;
      /* new y[j] = yj + alpha * yi */
