         y[j] = yj + alpha * yi;

       For odd k there is a center index c = k/2 that satisfies
       c == k-1-c, so its update reduces to:
         y[c] = (1 + alpha) * y_old[c];
     */
    {
      int k_minus_1 = k - 1;
      int half      = k >> 1;  /* floor(k/2) */
      int low  = 0;
      int high = k_minus_1;

      /* Process disjoint symmetric pairs (low, high). */
      for (i = 0; i < half; ++i, ++low, --high) {
        DATA_TYPE yi = y_[low];
        DATA_TYPE yj = y_[high];

        y_[low]  = yi + alpha * yj;
        y_[high] = yj + alpha * yi;
      }

      /* For odd k, update the center element, which is not touched above. */
      if (k & 1) {
        int c = half;  /* c == (k - 1) / 2 for odd k */
        y_[c] = y_[c] * (one + alpha);
      }
    }

    /* Append alpha at position k, as in the original algorithm. */
    y_[k] = alpha;
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(r));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_durbin (n,
		 POLYBENCH_ARRAY(r),
		 POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(r);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
