  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_durbin[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  /* Keep scalars in registers across the whole kernel. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  /* Local pointer aliases with restrict to help the optimizer.
     POLYBENCH_1D(...) decays to a pointer in function parameters. */
  DATA_TYPE * __restrict r_ptr = r;
  DATA_TYPE * __restrict y_ptr = y;

  int k;

#pragma scop
  /* k = 0 initialization (unchanged). */
  y_ptr[0] = -r_ptr[0];
  beta     = SCALAR_VAL(1.0);
  alpha    = -r_ptr[0];

  /* Main Durbin recursion: k = 1 .. _PB_N-1.
     This outer loop is inherently sequential because alpha, beta,
     and y[0..k] carry dependencies between iterations. */
  for (k = 1; k < _PB_N; k++)
  {
    /* beta = (1 - alpha^2) * beta;  (hoist alpha*alpha) */
    DATA_TYPE alpha_sq = alpha * alpha;
    beta = (SCALAR_VAL(1.0) - alpha_sq) * beta;

    /* sum = sum_{i=0}^{k-1} r[i] * y[k-1-i]
       This is algebraically equivalent to the original:
         sum += r[k-i-1] * y[i];
       but gives stride‑1 access to r, improving cache behavior.
       (Order of additions changes only up to FP round‑off.) */
    sum = SCALAR_VAL(0.0);

#pragma GCC ivdep
    for (int i = 0; i < k; i++)
    {
      sum += r_ptr[i] * y_ptr[k - i - 1];
    }

    /* alpha = -(r[k] + sum) / beta; */
    alpha = -(r_ptr[k] + sum) / beta;

    /* In-place symmetric update of y[0..k-1], eliminating the temporary
       buffer z[] used in the original code.

       Original:
         for (i = 0; i < k; i++)
           z[i] = y[i] + alpha * y[k-i-1];
         for (i = 0; i < k; i++)
           y[i] = z[i];

       New form:
         For each pair (i, j = k-1-i) we compute both y_new[i] and y_new[j]
         from the OLD values y_old[i], y_old[j]:
           y_new[i] = y_old[i] + alpha * y_old[j]
           y_new[j] = y_old[j] + alpha * y_old[i]

         This uses only two scalar temporaries per pair and does not require
         an extra array or extra pass over y. */
    {
      int half = k >> 1; /* integer division: k / 2 */

#pragma GCC ivdep
      for (int i = 0; i < half; i++)
      {
        int j = k - 1 - i;

        DATA_TYPE yi = y_ptr[i];
        DATA_TYPE yj = y_ptr[j];

        /* Pairwise simultaneous update using the old values. */
        DATA_TYPE new_yi = yi + alpha * yj;
        DATA_TYPE new_yj = yj + alpha * yi;

        y_ptr[i] = new_yi;
        y_ptr[j] = new_yj;
      }

      /* If k is odd, there is a center element c = k/2 that, in the
         original scheme, satisfies:
             y[c] = y[c] + alpha * y[c]  =>  y[c] *= (1 + alpha). */
      if (k & 1)
      {
        int c = k >> 1;
        y_ptr[c] = y_ptr[c] * (SCALAR_VAL(1.0) + alpha);
      }
    }

    /* Append alpha at position k (unchanged). */
    y_ptr[k] = alpha;
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(r));

